CELL_SRC[6] = r'''def make_historical_blocks(pre_index, m, n, max_donors=MAX_DONORS):
    """
    Cut the pre-treatment visit sequence into overlapping donor blocks.

    Each block supplies m pseudo-pre observations and the n observations that
    follow them, which stand in for the post-treatment horizon. When the number
    of feasible blocks exceeds max_donors, blocks are thinned evenly across the
    pre-period so the optimizer stays tractable without biasing toward either
    end of the history.
    """

    pre_index = list(pre_index)

    T0 = len(pre_index)

    N = T0 - m - n + 1

    if N < 1:

        raise ValueError(
            f"Infeasible block design: T0={T0}, m={m}, n={n}, N={N}"
        )

    all_starts = list(range(N))

    if max_donors is not None and N > max_donors:

        picks = np.linspace(0, N - 1, max_donors)

        all_starts = sorted(set(int(round(value)) for value in picks))

    blocks = []

    for donor_id, j in enumerate(all_starts, start=1):

        blocks.append(
            {
                "donor_id": donor_id,
                "start": j,
                "pre_positions": pre_index[j:j + m],
                "pseudo_post_positions": pre_index[j + m:j + m + n],
            }
        )

    return blocks
def solve_paper_weights(target, donor_matrix, selected_cols=None):
    """
    Solve for simplex weights that best reproduce the target block.

    Weights are non-negative and sum to one. When the donor Gram matrix is
    rank deficient, a small ridge on the null space keeps the solution unique
    without materially changing the fit.
    """

    target = np.asarray(target, dtype=float)
    donor_matrix = np.asarray(donor_matrix, dtype=float)

    if selected_cols is None:
        selected_cols = list(range(donor_matrix.shape[1]))

    X = donor_matrix[:, selected_cols]

    J = X.shape[1]

    if J < 1:
        raise ValueError("No donor columns supplied.")

    if J == 1:

        w = np.array([1.0])
        resid = target - X[:, 0]

        return {
            "weights": w,
            "mse": float(np.mean(resid ** 2)),
            "sse": float(np.sum(resid ** 2)),
            "null_penalty": 0.0,
            "objective": float(np.sum(resid ** 2)),
            "rank": 1,
            "n_null": 0,
            "ridge": 0.0,
            "converged": True,
        }

    gram = X.T @ X

    eigvals, eigvecs = np.linalg.eigh(gram)

    scale = max(float(np.max(np.abs(eigvals))), 1.0)

    tol = EIGEN_TOL_REL * scale

    null_mask = eigvals <= tol

    C2 = eigvecs[:, null_mask] if null_mask.any() else np.empty((J, 0))

    rank = int(np.linalg.matrix_rank(gram, tol=tol))

    ridge = PD_NULL_RIDGE_REL * scale if C2.shape[1] > 0 else 0.0

    def pieces(w):

        resid = target - X @ w

        sse = float(np.sum(resid ** 2))

        penalty = (
            float(ridge * np.sum((C2.T @ w) ** 2))
            if C2.shape[1]
            else 0.0
        )

        return sse, penalty

    def objective(w):

        sse, penalty = pieces(w)

        return sse + penalty

    # SLSQP occasionally stalls on the larger, more collinear problems that
    # daily data produces, reporting "Positive directional derivative for
    # linesearch" even though the point it reached is usable. Rather than
    # discard the whole case, retry from several starts and from a looser
    # tolerance, then accept the best feasible point found.

    single_mse = np.array(
        [float(np.mean((target - X[:, j]) ** 2)) for j in range(J)]
    )

    corner = np.zeros(J)
    corner[int(np.argmin(single_mse))] = 1.0

    starts = [np.full(J, 1.0 / J), corner]

    attempts = []

    for tolerance in [WEIGHT_OPT_TOL, 1e-9, 1e-6]:

        for x0 in starts:

            result = minimize(
                objective,
                x0,
                method="SLSQP",
                bounds=[(0.0, 1.0)] * J,
                constraints={
                    "type": "eq",
                    "fun": lambda w: np.sum(w) - 1.0,
                },
                options={
                    "ftol": tolerance,
                    "maxiter": WEIGHT_OPT_MAXITER,
                },
            )

            candidate = np.asarray(result.x, dtype=float)

            feasible = bool(
                np.isfinite(candidate).all()
                and (candidate >= -1e-6).all()
                and abs(candidate.sum() - 1.0) < 1e-4
            )

            if feasible:

                attempts.append(
                    (float(objective(candidate)), result.success, candidate)
                )

            if result.success and feasible:
                break

        if attempts and attempts[-1][1]:
            break

    if not attempts:

        # Nothing feasible was found, so fall back to the single best donor,
        # which is always feasible and is the natural degenerate solution.
        attempts.append((float(objective(corner)), False, corner))

    attempts.sort(key=lambda item: item[0])

    w = attempts[0][2].copy()

    converged = bool(attempts[0][1])

    w[np.abs(w) < 1e-12] = 0.0

    if w.sum() <= 0:
        raise RuntimeError("Estimated weights sum to zero.")

    w = w / w.sum()

    sse, penalty = pieces(w)

    return {
        "weights": w,
        "mse": float(sse / len(target)),
        "sse": sse,
        "null_penalty": penalty,
        "objective": sse + penalty,
        "rank": rank,
        "n_null": int(C2.shape[1]),
        "ridge": ridge,
        "converged": converged,
    }
print("Block and weight-solver functions defined.")
'''

