    ratios = {
        band: float(value * case["scalers"][band]["rho"])
        for band, value in feature_mse.items()
    }

    values = [v for v in ratios.values() if np.isfinite(v)]

    if not values:
        return np.nan, np.nan, ratios

    return float(np.mean(values)), float(np.max(values)), ratios
