def build_residual_series(site_id, sensor, band, spec="no_lag"):
    """
    Concatenate pre-treatment and post-treatment residuals into one series.

    Returns
    -------
    tuple
        (u, T0, n, post_dates) where u has length T = T0 + n and the post
        window occupies the final n positions.
    """

    obj = series_store[(site_id, sensor, band, spec)]

    pre = obj["pre_fit"].sort_values("date")

    u_pre = pre["y_star"].to_numpy(float) - pre["l_hat"].to_numpy(float)

    post = daily_effects.loc[
        daily_effects["site_id"].eq(site_id)
        & daily_effects["sensor"].eq(sensor)
        & daily_effects["band"].eq(band)
        & daily_effects["specification"].eq(spec)
    ].sort_values("date")

    u_post = post["effect_gamma_hat"].to_numpy(float)

    u = np.concatenate([u_pre, u_post])

    if not np.isfinite(u).all():
        raise ValueError("Residual series contains non-finite values.")

    return u, len(u_pre), len(u_post), post["date"].to_numpy()
def statistic(block, kind):
    """One statistic on one window of residuals."""

    root = np.sqrt(len(block))

    if kind == "mean":
        # CWZ Remark 1: signed, targets the average effect over time.
        return float(block.sum() / root)

    if kind == "inf":
        # The q to infinity limit of S_q. CWZ note it has high power when the
        # intervention has a large but only temporary effect.
        return float(np.max(np.abs(block)))

    q = float(kind)

    return float((np.sum(np.abs(block) ** q) / root) ** (1.0 / q))
def shc_bootstrap_draws(u_pre, n, kinds, rng):
    """
    Procedure A. Resample n pre-treatment residuals with replacement.

    Chen, Yang and Yang fn. 21: "we construct the null distribution of S by
    randomly sampling n observations with replacement from the pre-treatment
    residuals 1,000 times."
    """

    picks = rng.integers(0, len(u_pre), size=(SHC_BOOTSTRAP_DRAWS, n))

    blocks = u_pre[picks]

    return {
        kind: np.array([statistic(block, kind) for block in blocks])
        for kind in kinds
    }
def cwz_shift_draws(u, n, kinds):
    """
    Procedure B. Every statistic at every circular shift.

    CWZ's moving block set Pi_moving: pi_j maps i to i + j, wrapping at T.
    Shift zero leaves the window on the final n positions, the true post
    window, so the identity permutation is element zero.
    """

    T = len(u)

    base = np.arange(T - n, T)

    out = {kind: np.empty(T) for kind in kinds}

    for shift in range(T):

        block = u[(base - shift) % T]

        for kind in kinds:
            out[kind][shift] = statistic(block, kind)

    return out
def tail_p_value(values, observed, two_sided=False):
    """
    Share of the reference distribution at least as extreme as the observed.

    S_q is built so that large values reject, so the upper tail is the right
    one. The signed statistic is two-sided, since a move in either direction
    is of interest.
    """

    values = np.asarray(values, dtype=float)

    if two_sided:
        return float(np.mean(np.abs(values) >= np.abs(observed) - 1e-12))

    return float(np.mean(values >= observed - 1e-12))
def pointwise_interval(u_pre, gap, alpha):
    """
    CWZ Algorithm 1: a confidence interval for a single period's effect.

    For the pointwise null H0: theta_t = theta, the data under the null are the
    pre-treatment periods plus period t alone, so n = 1 and the statistic
    collapses to |gap - theta|. The moving-block p-value is

        p(theta) = ( 1 + #{ s <= T0 : |u_s| >= |gap - theta| } ) / (T0 + 1)

    and the interval is { theta : p(theta) > alpha }, centred on the estimated
    gap with half width equal to the j-th largest absolute pre-treatment
    residual, where j is fixed by the level. Exact, with no grid search over
    theta and no quantile convention.
    """

    absolute = np.sort(np.abs(u_pre))[::-1]

    T0 = len(absolute)

    needed = int(np.ceil(alpha * (T0 + 1))) - 1

    if needed <= 0:
        return -np.inf, np.inf, np.inf

    half = float(absolute[needed - 1])

    return gap - half, gap + half, half
def lag_one_autocorrelation(values):
    """
    Lag-one autocorrelation of the pre-treatment residuals.

    Procedure A resamples residuals independently, which is only valid under
    CWZ Assumption 2.1. A value well outside plus or minus 2 / sqrt(T0) is
    evidence of the serial dependence that makes Assumption 2.2, and therefore
    the moving-block set of procedure B, the applicable case.
    """

    values = np.asarray(values, dtype=float)

    centred = values - values.mean()

    denominator = float(np.sum(centred ** 2))

    if denominator <= 1e-12:
        return np.nan

    return float(np.sum(centred[:-1] * centred[1:]) / denominator)
